objects = {
    'demo color1 upper': {'in': [(0,3),(1,2),(1,3),(1,4)], 'out': [(5,3),(6,2),(6,3),(6,4)]},
    'demo color1 lower': {'in': [(5,2),(5,3),(5,4),(6,1),(6,2),(6,3),(6,4)], 'out': [(8,4),(8,5),(8,6),(9,3),(9,4),(9,5),(9,6)]},
    'demo color6 upper-right': {'in': [(2,6),(3,6),(3,7)], 'out': [(5,0),(6,0),(6,1)]},
    'demo color6 left': {'in': [(3,0),(3,1),(4,0),(4,1)], 'out': [(8,0),(8,1),(9,0),(9,1)]},
}
for name, obj in objects.items():
    ins, outs = obj['in'], obj['out']
    assert len(ins) == len(outs)
    shifts = {(r2-r1,c2-c1) for (r1,c1),(r2,c2) in zip(ins,outs)}
    print(f'{name}: cells={len(ins)}, translation={next(iter(shifts)) if len(shifts)==1 else "not pure translation"}')

